(function(SK){
  'use strict';
  const {isoDay,addDays,monday,daysBetween,dateLabel,clone,uid,sports,goals}=SK;
  const root=document.getElementById('root'),modalRoot=document.getElementById('modal-root');
  let state=null,demo=false,view='overview',busy=false,anchor=isoDay(),selectedDay=isoDay();
  let calendarMode=innerWidth<640?'week':'month',syncLabel='Lokaal opgeslagen',modalLocked=false,focusBefore=null,shareUrl='',lastFocusSync=0;
  let stravaStatus={available:null,connected:false,athleteName:'',lastSync:null};
  let toastTimer;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=n=>new Intl.NumberFormat('nl-NL',{maximumFractionDigits:1}).format(n||0);
  const paceDisplay=value=>{const sec=Math.max(0,Math.round(Number(value||0)*60));return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;};
  const parsePace=value=>{const text=String(value||'').trim();const m=text.match(/^(\d{1,2}):([0-5]\d)$/);if(!m)throw new Error('Vul je tempo in als minuten:seconden per km, bijvoorbeeld 6:30.');const pace=Number(m[1])+Number(m[2])/60;if(pace<3||pace>15)throw new Error('Vul een rustig tempo in tussen 3:00 en 15:00 min/km.');return pace;};
  const formatSeconds=value=>{if(!Number.isFinite(Number(value))||Number(value)<=0)return '--';const sec=Math.round(Number(value));const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),ss=String(sec%60).padStart(2,'0');return h?`${h}:${String(m).padStart(2,'0')}:${ss}`:`${m}:${ss}`;};
  const actualPace=w=>w?.actual?.km>0&&w?.actual?.minutes>0?formatSeconds((Number(w.external?.movingSeconds)||w.actual.minutes*60)/w.actual.km)+'/km':'';
  const runKindLabel=kind=>({easy:'Kort',short:'Kort',long:'Lang',interval:'Interval',race:'Doeldag'}[kind]||'Kort');
  const icons={
    compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5Z"/>',
    grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h2m4 0h2"/>',
    spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4"/>',
    chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',
    settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',
    run:'<circle cx="15" cy="4" r="2"/><path d="m12 9 3 4 4 1M7 10l4-2 3 1-4 7-5 4m5-4 5 1 1 4"/>',
    strength:'<path d="M7 8v8m10-8v8M7 12h10M4 6v12m16-12v12M2 10v4m20-4v4"/>',
    cycle:'<circle cx="5" cy="16" r="4"/><circle cx="19" cy="16" r="4"/><path d="m5 16 5-9 5 9H5m5-9 8 1 1 8M8 5h4m3-3h3l1 5"/>',
    walk:'<circle cx="13" cy="4" r="2"/><path d="m10 10 2-3 3 4 4 1m-7-5-2 8-3 6m3-6 5 2 1 5M7 13l3-3"/>',
    target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',
    cloud:'<path d="M7 18a5 5 0 1 1 1-10 6 6 0 0 1 11 2 4 4 0 0 1 0 8M12 11v10m-3-3 3 3 3-3"/>',
    share:'<path d="M12 16V3m-5 5 5-5 5 5M5 13v7h14v-7"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
    left:'<path d="m15 6-6 6 6 6"/>',right:'<path d="m9 6 6 6-6 6"/>',
    check:'<path d="m5 12 4 4L19 6"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>',
    lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
    logout:'<path d="M9 4H4v16h5m6-13 5 5-5 5M9 12h11"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    trash:'<path d="M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',
    refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 8a7 7 0 0 1 12-3l3 3M4 16l3 3a7 7 0 0 0 12-3"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',
    bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>'
  };
  const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.run}</svg>`;
  const btn=(label,action,extra='',className='')=>`<button type="button" class="btn ${className}" data-action="${action}" ${extra}>${label}</button>`;
  const brand=mobile=>`<div class="brand ${mobile?'mobile-brand':''}"><span class="brand-mark logo-mark"><img src="./assets/icon-192.png" alt="" width="30" height="30"></span><span>MijnLoop</span></div>`;
  const days=['Maandag','Dinsdag','Woensdag','Donderdag','Vrijdag','Zaterdag','Zondag'];
  const shortDays=['Ma','Di','Wo','Do','Vr','Za','Zo'];
  const opts=(obj,value)=>Object.entries(obj).map(([k,v])=>`<option value="${esc(k)}" ${k===String(value)?'selected':''}>${esc(v)}</option>`).join('');
  function toast(text){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),5500);}
  function showError(form,text){if(!form.isConnected){toast(text);return;}const el=form.querySelector('.form-error');if(el){el.textContent=text;el.scrollIntoView({block:'nearest'});}else toast(text);}
  function showModal(title,subtitle,content,{wide=false,locked=false}={}){
    focusBefore=document.activeElement;modalLocked=locked;
    modalRoot.innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div>${locked?'':btn(icon('close'),'close-modal','aria-label="Sluiten"','ghost icon-btn')}</div>${content}</section></div>`;
    document.body.style.overflow='hidden';setTimeout(()=>modalRoot.querySelector('input:not([type=checkbox]),select,button')?.focus(),20);
  }
  function closeModal(){if(busy)return;modalRoot.innerHTML='';document.body.style.overflow='';modalLocked=false;focusBefore?.focus();}
  async function commit(candidate,message='Opgeslagen'){
    SK.validateState(candidate);
    if(demo){state=candidate;syncLabel='Alleen demo';}
    else {try{state=await SK.DB.save(candidate);syncLabel='Opgeslagen';}catch(e){if(e.code==='CONFLICT'){const data=await SK.DB.load();state=data.state;render();}throw e;}}
    render();if(message)toast(message);
  }
  function notificationPrefs(){return state?SK.notificationSettings(state):SK.notificationDefaults;}
  function attention(){return state?SK.attentionItems(state,new Date()):[];}
  function notificationPermission(){return ('Notification' in window)?Notification.permission:'unsupported';}
  function notifiedStoreKey(){return 'mijnloop-notified-v1:'+(demo?'demo':SK.DB.user?.id||'local');}
  function readNotified(){try{const v=JSON.parse(localStorage.getItem(notifiedStoreKey())||'{}');return v&&typeof v==='object'?v:{};}catch{return {};}}
  function writeNotified(v){try{const entries=Object.entries(v).sort((a,b)=>Number(b[1]||0)-Number(a[1]||0)).slice(0,120);localStorage.setItem(notifiedStoreKey(),JSON.stringify(Object.fromEntries(entries)));}catch{}}
  async function updateAppBadge(){
    if(!state)return;const pref=notificationPrefs(),count=attention().length;
    try{
      if(!pref.enabled||!pref.appBadge||!count){if('clearAppBadge' in navigator)await navigator.clearAppBadge();return;}
      if('setAppBadge' in navigator)await navigator.setAppBadge(count);
    }catch{}
  }
  async function showDeviceNotification(item){
    if(notificationPermission()!=='granted')return false;
    const options={body:item.body,icon:'./assets/icon-192.png',badge:'./assets/icon-192.png',tag:'mijnloop-'+item.key.replace(/[^a-z0-9_-]/gi,'-').slice(0,100),data:{url:'./'},renotify:false};
    try{if('serviceWorker' in navigator){const reg=await navigator.serviceWorker.ready;await reg.showNotification(item.title,options);return true;}}catch{}
    try{new Notification(item.title,options);return true;}catch{return false;}
  }
  async function maybeNotify(){
    if(!state)return;const pref=notificationPrefs();if(!pref.enabled||!pref.systemNotifications||notificationPermission()!=='granted')return;
    const sent=readNotified();let changed=false;
    for(const item of attention())if(!sent[item.key]){if(await showDeviceNotification(item)){sent[item.key]=Date.now();changed=true;}}
    if(changed)writeNotified(sent);
  }
  function notificationCenter(){
    const items=attention(),pref=notificationPrefs();
    const list=items.length?items.map(item=>`<div class="attention-item"><div class="attention-glyph">${icon(item.category==='pending'?'clock':'bell',19)}</div><div><strong>${esc(item.title)}</strong><p>${esc(item.body)}</p></div>${btn(item.category==='pending'?'Invullen':'Bekijken',item.category==='pending'?'log':'detail',`data-id="${esc(item.workoutId)}"`,'compact')}</div>`).join(''):'<div class="empty-state">Er staat nu niets open waarvoor je een melding hebt ingeschakeld.</div>';
    showModal('Meldingen','Aandachtspunten uit je huidige planning.',`${list}<div class="notice mt"><strong>Badge:</strong> ${items.length} openstaand${items.length===1?' punt':'e punten'}. Alleen ingeschakelde categorieën tellen mee.</div><div class="modal-actions">${btn('Meldingsinstellingen','nav-notifications','','')}${btn('Sluiten','close-modal','','primary')}</div>`);
  }
  function notificationSettingsCard(){
    const n=notificationPrefs(),permission=notificationPermission();
    const status=permission==='granted'?'Toegestaan':permission==='denied'?'Geblokkeerd':permission==='default'?'Nog niet gevraagd':'Niet ondersteund';
    const allow=permission==='default'?btn('Meldingen toestaan','enable-notifications','','compact primary'):permission==='granted'?btn('Test melding','test-notification','','compact'):'';
    return `<fieldset><legend>Meldingen & badges</legend><p class="small muted mb">Kies zelf welke aandachtspunten meetellen. De teller verschijnt in MijnLoop en, op ondersteunde Home Screen-webapps, ook op het app-icoon.</p><div class="notification-settings"><label class="checkline"><input name="notificationsEnabled" type="checkbox" ${n.enabled?'checked':''}><span>Meldingen en aandachtsteller gebruiken</span></label><label class="checkline"><input name="appBadge" type="checkbox" ${n.appBadge?'checked':''}><span>Badge op app-icoon tonen<span class="field-help" style="display:block">Op iPhone werkt dit wanneer MijnLoop via 'Zet op beginscherm' is geinstalleerd en meldingen zijn toegestaan.</span></span></label><label class="checkline"><input name="systemNotifications" type="checkbox" ${n.systemNotifications?'checked':''}><span>Systeemmeldingen tonen</span></label><div class="notification-category"><label class="checkline"><input name="notifyUpcoming" type="checkbox" ${n.upcoming?'checked':''}><span>Aankomende sportactiviteit</span></label><label>Hoe lang vooraf<select name="upcomingHours">${opts({'1':'1 uur','2':'2 uur','4':'4 uur','8':'8 uur','12':'12 uur','24':'24 uur','48':'48 uur'},n.upcomingHours)}</select></label></div><div class="notification-category"><label class="checkline"><input name="notifyPending" type="checkbox" ${n.pending?'checked':''}><span>Geplande training is voorbij en nog niet ingevuld</span></label><label>Herinnering na einde<select name="pendingDelayMinutes">${opts({'0':'Direct','15':'15 minuten','30':'30 minuten','60':'1 uur','120':'2 uur','180':'3 uur'},n.pendingDelayMinutes)}</select></label></div><div class="notice"><strong>Meldingsstatus op dit apparaat:</strong> ${esc(status)}. ${allow}</div><p class="small muted">MijnLoop werkt zonder extra Supabase-wijziging: badges en systeemmeldingen worden bijgewerkt wanneer de app geopend of actief is. Volledig zelfstandige achtergrondpush terwijl de app gesloten is, vraagt later een aparte pushservice.</p></div></fieldset>`;
  }
  function renderAuth(){
    state=null;shareUrl='';
    const ready=globalThis.MijnLoopLocalAuth?.hasUsers?.();
    root.innerHTML=`<div class="auth-layout"><section class="auth-story">${brand(false)}<h1>Jouw ritme.<br>Jouw doel.<br><em>Een plan dat<br>meebeweegt.</em></h1><p>Niet elke training gaat zoals gepland. Je agenda mag zich aanpassen aan jou. Niet andersom.</p><div class="story-preview"><div class="eyebrow" style="color:#b8d49f">Je hebt toch bewogen</div><div style="margin:13px 0"><span class="preview-strike">10 km gepland</span><span class="preview-new">5 km gelopen</span></div><p class="small" style="color:#b6cdbb">Registreer wat lukte. De planner bekijkt de komende trainingen opnieuw, zonder inhaalschuld.</p></div><div class="story-foot">Lokaal account &nbsp; / &nbsp; Jouw vaste momenten &nbsp; / &nbsp; Jouw tempo</div></section><main class="auth-form-wrap" id="main"><div class="auth-form"><div class="eyebrow">Welkom bij MijnLoop</div><h2>Goed je te zien.</h2><p>Log lokaal in op dit apparaat. Je account en sportgegevens staan in deze browser, niet in Supabase Auth.</p>${ready?`<form id="login-form"><div class="form-error" role="alert"></div><label>Gebruikersnaam<input name="username" type="text" autocomplete="username" placeholder="jouw gebruikersnaam" required></label><label>Wachtwoord<input name="password" type="password" autocomplete="current-password" placeholder="Jouw lokale wachtwoord" required></label><button class="btn primary" type="submit">Inloggen ${icon('arrow',17)}</button></form>`:`<div class="notice mt"><strong>Nog geen lokale accounts.</strong><br>Open eerst de losse beheerderspagina en maak daar de beheerder en gebruikers aan.</div>`}<div class="button-row" style="justify-content:center;margin-top:12px"><a class="btn ghost compact" href="./admin.html">Open beheerderspagina</a></div><div class="auth-bottom">${btn('Bekijk de interactieve demo '+icon('arrow',16),'start-demo','','ghost')}<p>Fictieve gegevens. Geen account nodig voor de demo.</p></div><div class="security-note mt">${icon('shield',16)}<span>Wachtwoorden worden lokaal gehasht voor de logincontrole en daarnaast bewust leesbaar opgeslagen voor de beheerder. Gebruik MijnLoop daarom alleen op een vertrouwd browserprofiel.</span></div></div></main></div>`;
  }
  function shell(){
    const nav=[['overview','grid','Overzicht'],['calendar','calendar','Agenda'],['coach','spark','Coach'],['progress','chart','Voortgang'],['settings','settings','Instellingen']];
    const name=state.profile?.name||'Mijn account', initials=name.slice(0,1).toUpperCase();
    return `<div class="app-shell"><aside class="sidebar">${brand(false)}<div class="brand-sub">JOUW RITME, JOUW DOEL</div><nav class="nav" aria-label="Hoofdnavigatie">${nav.map(([v,i,t])=>`<button data-action="nav" data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''} title="${t}">${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="personal-note">${icon('shield',20)}<strong>Jouw eigen koers</strong>Geen gedeelde doelen. Geen vergelijking. Alleen jouw planning en voortgang.</div><div class="sidebar-account"><div class="avatar">${esc(initials)}</div><div class="account-text"><strong>${esc(name)}</strong><span class="tiny" style="color:#93ad9c">${demo?'Demo-account':'Persoonlijk account'}</span></div><button title="Uitloggen" aria-label="Uitloggen" data-action="logout">${icon('logout',18)}</button></div></div></aside><div class="content"><header class="topbar"><div class="breadcrumb">MijnLoop &nbsp; / &nbsp; <b>${nav.find(n=>n[0]===view)?.[2]||'Overzicht'}</b></div>${brand(true)}<div class="top-actions"><div class="sync-state"><i class="sync-dot"></i>${esc(demo?'Demogegevens':syncLabel)}</div>${btn(icon('bell',17)+(attention().length?`<span class="attention-count">${attention().length}</span>`:''),'notifications','title="Meldingen" aria-label="Meldingen"','icon-btn attention-btn')}${btn(icon('refresh',17),'sync','title="Synchroniseren" aria-label="Synchroniseren"','icon-btn')}${btn(icon('share',16)+'<span>Agenda exporteren</span>','share','title="Agenda exporteren" aria-label="Agenda exporteren"')}${btn(icon('logout',16),'logout','aria-label="Uitloggen" title="Uitloggen"','icon-btn')}</div></header>${demo?'<div class="demo-banner"><span><strong>Interactieve demo.</strong> Alle trainingen en afstanden zijn fictieve voorbeelden.</span><button data-action="reset-demo">Demo herstellen</button></div>':''}<main id="main">${page()}</main><footer class="footer-note">MijnLoop v21 &nbsp; &middot; &nbsp; Automatische planner, geen medisch advies &nbsp; &middot; &nbsp; Europe/Amsterdam</footer></div></div>`;
  }
  function render(){if(!state){renderAuth();return;}if(!state.profile)view='settings';root.innerHTML=shell();setTimeout(()=>{updateAppBadge();maybeNotify();},0);}
  function page(){return view==='calendar'?calendarPage():view==='coach'?coachPage():view==='progress'?progressPage():view==='settings'?settingsPage():overviewPage();}
  function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${actions||`<div class="date-label">${dateLabel(isoDay(),{weekday:'long'})}</div>`}</div>`;}
  function upcoming(){return state.workouts.filter(w=>['planned','held'].includes(w.status)&&w.date>=isoDay()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));}
  function weeklyStats(){const m=monday(isoDay()),end=addDays(m,6);const ws=state.workouts.filter(w=>w.date>=m&&w.date<=end&&w.status!=='cancelled');return {planned:ws.filter(w=>w.sport==='run').reduce((a,w)=>a+(w.actual?.plannedKm??w.km),0),actual:ws.filter(w=>w.sport==='run').reduce((a,w)=>a+(w.actual?.km||0),0),minutes:ws.reduce((a,w)=>a+(w.actual?.minutes||0),0),done:ws.filter(w=>w.status==='done').length,total:ws.length};}
  function tags(w){let out='';if(w.status==='done')out+='<span class="tag">Afgerond</span>';if(w.status==='skipped')out+='<span class="tag muted">Overgeslagen</span>';if(w.status==='held')out+='<span class="tag red">Gepauzeerd</span>';if(w.external?.provider==='strava')out+='<span class="tag strava-tag">Strava</span>';if(w.actual?.needsReview)out+='<span class="tag amber">Inspanning bevestigen</span>';if(w.adaptation&&w.km<w.baseKm)out+='<span class="tag lime">Aangepast</span>';if(w.locked)out+=`<span class="tag amber">${icon('lock',10)} Vastgezet</span>`;else if(w.source==='plan')out+='<span class="tag muted">Vast moment</span>';if(w.status==='planned'&&w.date<isoDay())out+='<span class="tag amber">Nog invullen</span>';return out?`<div class="tags">${out}</div>`:'';}
  function workoutCard(w,{date=true}={}){
    const actual=w.actual&&['done','skipped'].includes(w.status),km=actual?w.actual.km:w.km,min=actual?w.actual.minutes:w.minutes;
    const action=w.date<=isoDay()&&w.status!=='cancelled'?'log':'detail';
    const type=w.sport==='run'?`<span class="tag muted">${esc(runKindLabel(w.kind))}</span>`:'';
    const interval=w.interval?.summary?`<div class="workout-meta interval-meta">${esc(w.interval.summary)}</div>`:'';
    return `<div class="workout ${esc(w.status)}"><div class="sport-icon ${esc(w.sport)}">${icon(w.status==='done'?'check':w.sport,21)}</div><div class="workout-info"><strong>${esc(w.title)}</strong><div class="workout-meta">${date?esc(dateLabel(w.date,{weekday:'short'}))+' &middot; ':''}${esc(w.time)} &middot; ${num(min)} min${actual&&w.sport==='run'&&km>0?' &middot; '+esc(actualPace(w)):''} ${type}</div>${interval}${tags(w)}</div><div class="workout-distance">${num(w.sport==='run'?km:min)} <small>${w.sport==='run'?'km':'min'}</small></div>${btn(actual?'Bekijken':action==='log'?'Invullen':icon('right',16),action,`data-id="${esc(w.id)}" aria-label="${action==='log'?'Training registreren':'Training bekijken'}"`,'compact')}</div>`;
  }
  function weekStrip(){const m=monday(isoDay());return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const day=addDays(m,i),ws=state.workouts.filter(w=>w.date===day&&w.status!=='cancelled');return `<button class="day-chip ${day===isoDay()?'today':''} ${selectedDay===day?'selected':''}" data-action="day" data-date="${day}" aria-label="${esc(dateLabel(day,{weekday:'long'}))}"><span>${shortDays[i]}</span><strong>${+day.slice(-2)}</strong><span class="dots">${ws.slice(0,3).map(w=>`<i class="dot ${w.sport!=='run'?'alt':''}"></i>`).join('')}</span></button>`;}).join('')}</div>`;}
  function overviewPage(){
    if(!state.profile)return settingsPage();const p=state.profile,next=upcoming()[0],stats=weeklyStats();const ws=state.workouts.filter(w=>w.date===selectedDay&&w.status!=='cancelled').sort((a,b)=>a.time.localeCompare(b.time));const last=state.adjustments[0],warnings=SK.warnings(state);
    return heading(`Jouw ritme, ${p.name.replace(' (demo)','')}.`,'Een goed plan beweegt mee met het echte leven.')+`${state.hold?'<div class="notice danger">Je planning staat gepauzeerd. Bekijk Coach voordat je weer opbouwt.</div>':''}<div class="dashboard-grid"><div class="stack"><div><section class="card hero"><div class="eyebrow">${state.hold?'Even pas op de plaats':next?'Jouw volgende stap':'Ruimte voor beweging'}</div><h2>${state.hold?'Herstel gaat voor.':next?esc(next.title):'Maak ruimte voor je doel.'}</h2><p>${state.hold?'Geen inhaalkilometers. Hervat je planning bewust wanneer dat weer passend is.':next?`${esc(dateLabel(next.date,{weekday:'long'}))} om ${esc(next.time)} &middot; ${num(next.sport==='run'?next.km:next.minutes)} ${next.sport==='run'?'km':'min'} &middot; ${next.sport==='run'?esc(runKindLabel(next.kind)):esc(sports[next.sport])}`:'Je eigen vaste momenten en startniveau vormen de basis.'}</p><div class="hero-footer">${state.hold?btn('Bekijk je planning '+icon('arrow',16),'nav','data-view="coach"','lime'):next?btn(next.date<=isoDay()?'Training invullen '+icon('arrow',16):'Bekijk training '+icon('arrow',16),next.date<=isoDay()?'log':'detail',`data-id="${esc(next.id)}"`,'lime'):btn('Plan je week '+icon('arrow',16),'nav','data-view="settings"','lime')}<span class="small">${p.autoAdapt?'Automatisch aanpassen staat aan':'Handmatig beoordelen staat aan'}</span></div></section><div class="mini-stats"><div class="stat-card"><div class="stat-top">Deze week gelopen ${icon('run',16)}</div><div class="stat-number">${num(stats.actual)} <small>km</small></div><div class="stat-caption">${num(stats.planned)} km gepland</div><div class="progress-line"><span style="width:${Math.min(100,stats.planned?stats.actual/stats.planned*100:0)}%"></span></div></div><div class="stat-card"><div class="stat-top">Trainingen ${icon('check',16)}</div><div class="stat-number">${stats.done} <small>/ ${stats.total}</small></div><div class="stat-caption">afgerond deze week</div></div><div class="stat-card"><div class="stat-top">Bewogen ${icon('clock',16)}</div><div class="stat-number">${num(stats.minutes)} <small>min</small></div><div class="stat-caption">alle geregistreerde sporten</div></div></div></div><section class="card"><div class="card-header"><div><h2>Jouw week</h2><p>${dateLabel(monday(isoDay()))} - ${dateLabel(addDays(monday(isoDay()),6))}</p></div>${btn('Hele agenda '+icon('arrow',14),'nav','data-view="calendar"','ghost compact')}</div>${weekStrip()}<div class="section-row"><h3>${selectedDay===isoDay()?'Vandaag':dateLabel(selectedDay,{weekday:'long'})}</h3>${btn(icon('plus',15)+' Activiteit','add-workout',`data-date="${selectedDay}"`,'ghost compact')}</div><div class="workout-list">${ws.length?ws.map(w=>workoutCard(w,{date:false})).join(''):'<div class="empty">Geen sportmoment gepland.<br>Je hoeft niet elke vrije dag op te vullen.</div>'}</div></section><section class="card"><div class="card-header"><h2>Daarna op de planning</h2><span class="tag muted">Komende dagen</span></div><div class="workout-list">${upcoming().filter(w=>w.date>isoDay()).slice(0,3).map(w=>workoutCard(w)).join('')||'<div class="empty">Stel je vaste sportmomenten in.</div>'}</div></section></div><div class="stack"><section class="card coach-card"><div class="coach-glyph">${icon('spark',23)}</div><div class="eyebrow" style="color:#708850;margin-bottom:10px">De planner denkt mee</div><h3>${esc(last?.title||'Niet meer doen. Passend doen.')}</h3><p>${esc(last?.detail||'Vul na je training in wat je werkelijk hebt gedaan. De planner kijkt naar afstand, inspanning en de reden van een afwijking.')}</p>${btn('Bekijk aanpassingen '+icon('arrow',14),'nav','data-view="coach"','ghost compact mt')}<div class="card-footer">Vaste regels &middot; automatische beoordeling na registratie</div></section><section class="card"><div class="card-header"><h2>Jouw doel</h2>${icon('target',20)}</div><div class="goal-row"><div class="goal-icon">${icon('target',28)}</div><div><h3>${esc(goals[p.goal])}</h3><p>${p.raceDate?dateLabel(p.raceDate,{year:'numeric'}):'Op jouw eigen tempo'}</p></div></div><div class="key-value"><span>Huidige basis</span><strong>${num(p.baseWeeklyKm)} km/week</strong></div><div class="key-value"><span>Vaste sportmomenten</span><strong>${state.slots.length} per week</strong></div><div class="key-value"><span>Doeldatum</span><strong>${p.raceDate?`${daysBetween(isoDay(),p.raceDate)} dagen`:'Geen einddatum'}</strong></div>${btn('Mijn doel aanpassen','nav','data-view="settings"','ghost compact mt')}</section><section class="card"><div class="card-header"><h2>Goed om te weten</h2>${icon('info',18)}</div><p class="small muted">${warnings.length?esc(warnings[0]):'Een kortere training is informatie, geen mislukking. Vul ook in waarom je minder deed: tijdgebrek is iets anders dan zware benen.'}</p><div class="divider"></div><div class="security-note">${icon('shield',17)}<span>Je collega heeft een eigen account, een eigen doel en een volledig eigen planning.</span></div></section></div></div>`;
  }
  function calendarPage(){
    const first=anchor.slice(0,7)+'-01';let start,end,title;
    if(calendarMode==='month'){start=monday(first);end=addDays(start,41);title=dateLabel(first,{month:'long',year:'numeric',day:undefined});}else{start=monday(anchor);end=addDays(start,6);title=`${dateLabel(start)} - ${dateLabel(end)}`;}
    const ws=state.workouts.filter(w=>w.date>=start&&w.date<=end&&w.status!=='cancelled').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
    let content='';
    if(calendarMode==='month')content=`<div class="calendar-grid">${shortDays.map(d=>`<div class="calendar-label">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const day=addDays(start,i);return `<div class="calendar-cell ${day===isoDay()?'today':''} ${day.slice(0,7)!==first.slice(0,7)?'outside':''}"><span class="cell-date">${+day.slice(-2)}</span>${ws.filter(w=>w.date===day).map(w=>`<button class="calendar-event ${esc(w.sport)} ${esc(w.status)}" data-action="detail" data-id="${esc(w.id)}"><span class="time">${esc(w.time)}${w.status==='done'?' &#10003;':''}</span><br>${esc(w.sport==='run'?(w.kind==='interval'&&w.interval?.summary?`Interval ${w.interval.summary}`:w.kind==='long'?'Lange duurloop':w.kind==='race'?'Doeldag':'Korte loop'):sports[w.sport])}${w.sport==='run'?`<br>${num(w.actual?.km??w.km)} km`:''}${w.status==='held'?'<br>Gepauzeerd':''}</button>`).join('')}</div>`;}).join('')}</div>`;
    else content=Array.from({length:7},(_,i)=>{const day=addDays(start,i),list=ws.filter(w=>w.date===day);return `<div class="list-day-label"><span>${esc(dateLabel(day,{weekday:'long'}))}${day===isoDay()?' &middot; vandaag':''}</span>${btn(icon('plus',13),'add-workout',`data-date="${day}" aria-label="Activiteit toevoegen op ${day}"`,'ghost compact')}</div><div class="workout-list">${list.length?list.map(w=>workoutCard(w,{date:false})).join(''):'<p class="small muted" style="padding:5px 0 10px">Vrij / herstel</p>'}</div>`;}).join('');
    return heading('Jouw sportagenda.','Vaste momenten. Ruimte om aan te passen.',`<div class="button-row">${btn('Opnieuw beoordelen','recalculate','','ghost')}${btn(icon('plus',16)+' Activiteit','add-workout','','primary')}</div>`)+`<section class="card"><div class="toolbar"><div class="button-row">${btn(icon('left',16),'cal-prev','aria-label="Vorige periode"','icon-btn')}<div class="week-title">${esc(title)}</div>${btn(icon('right',16),'cal-next','aria-label="Volgende periode"','icon-btn')}${btn('Vandaag','cal-today','','ghost compact')}</div><div class="segmented"><button class="${calendarMode==='week'?'active':''}" data-action="cal-mode" data-mode="week">Week</button><button class="${calendarMode==='month'?'active':''}" data-action="cal-mode" data-mode="month">Maand</button></div></div>${content}</section><div class="notice mt">Wijzig trainingen in MijnLoop. Het agenda-abonnement neemt deze wijzigingen over zodra je agenda-app ververst. Bestaande priveafspraken worden in deze versie niet ingelezen.</div>`;
  }
  function coachPage(){
    const last=state.adjustments;
    return heading('Lokale coach.','Je schema past zich aan met vaste, controleerbare hardloopregels.')+`<div class="settings-grid"><div class="stack"><section class="card coach-card"><div class="card-header"><div><h2>${state.hold?'Je planning staat op pauze':'Jij loopt. Je schema beweegt mee.'}</h2><p>Automatisch na het registreren van een activiteit</p></div>${icon('run',27)}</div><p>MijnLoop vergelijkt wat gepland was met wat je werkelijk liep. Een comfortabele goede reeks kan de eerstvolgende vergelijkbare loop maximaal een paar procent verhogen. Vermoeidheid, zware inspanning of herhaald inkorten verlaagt tijdelijk de belasting. Tijdgebrek en slecht weer worden milder behandeld dan fysieke vermoeidheid. Pijn of ziekte pauzeert de planning.</p><div class="button-row mt">${state.hold?btn('Planning bewust hervatten','resume','','primary'):btn('Schema nu opnieuw beoordelen','recalculate','','primary')}</div></section><section class="card"><div class="card-header"><h2>Wat is er aangepast?</h2><div class="button-row"><span class="tag muted">${last.length} beoordelingen</span>${last.length?btn('Coach resetten','reset-coach','','danger compact'):''}</div></div>${last.length?last.slice(0,20).map(a=>`<article class="audit"><div class="audit-head"><h3>${esc(a.title)}</h3><span class="tiny muted">${esc(new Date(a.at).toLocaleString('nl-NL',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))}</span></div><p>${esc(a.detail)}</p>${a.changes.slice(0,8).map(c=>`<div class="change"><span>${esc(c.title)} &middot; ${esc(dateLabel(c.after.date))}</span><b>${c.after.status==='held'?'Gepauzeerd':c.after.status==='cancelled'?'Verwijderd':`${num(c.before.km)} &rarr; ${num(c.after.km)} km`}</b></div>`).join('')}${a.changes.length>8?`<p class="tiny">En ${a.changes.length-8} andere wijzigingen; zichtbaar in je agenda.</p>`:''}</article>`).join(''):'<div class="empty">Vul een training in om je eerste lokale beoordeling te zien.</div>'}</section></div><div class="stack"><section class="card"><div class="card-header"><div><h2>Zo past MijnLoop lokaal aan</h2><p>Volledig lokale trainingslogica</p></div>${icon('target',20)}</div><div class="key-value"><span>Goede reeks</span><strong>max. +3%</strong></div><div class="key-value"><span>Vermoeid / zwaar</span><strong>tijdelijk ongeveer -18%</strong></div><div class="key-value"><span>Meerdere moeilijke trainingen</span><strong>opbouw terug</strong></div><div class="key-value"><span>Tijdgebrek / weer</span><strong>geen inhaalschuld</strong></div><div class="key-value"><span>Pijn / ziekte</span><strong>planning pauzeren</strong></div><p class="small muted mt">De voorgerekende 4-52-wekenmodellen blijven altijd de bovengrens. Een goede training zorgt dus niet voor een plotselinge sprong of een extra zware intervaltraining.</p></section><section class="card"><h3>Hardloopmodel</h3><p class="small muted mt">De planning combineert basis-, opbouw-, herstel-, piek- en taperweken. De lange duurloop wordt vanuit je doeldatum terug gepland naar een piek voor de taper. Intervaldagen krijgen een concrete training; lange duurlopen blijven rustig. Voor een marathon is 32 km de maximale geplande trainingsduurloop.</p><div class="divider"></div><p class="small muted">Andere sporten blijven losse sportmomenten en worden niet omgerekend naar hardloopkilometers.</p><div class="divider"></div><p class="small muted">Dit is trainingssoftware en geen medische diagnose of individuele wedstrijdgarantie.</p></section></div></div>`;
  }
  function progressPage(){
    const today=isoDay(),m=monday(today),weeks=Array.from({length:8},(_,i)=>{const start=addDays(m,-7*(7-i)),end=addDays(start,6),ws=state.workouts.filter(w=>w.sport==='run'&&w.date>=start&&w.date<=end&&w.status!=='cancelled');return {start,actual:ws.reduce((a,w)=>a+(w.actual?.km||0),0),planned:ws.reduce((a,w)=>a+(w.actual?.plannedKm??w.km),0)};});
    const max=Math.max(1,...weeks.flatMap(w=>[w.actual,w.planned]));const done=state.workouts.filter(w=>w.actual&&w.status==='done').sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));
    const runs=done.filter(w=>w.sport==='run');const allKm=runs.reduce((a,w)=>a+w.actual.km,0),minutes=done.reduce((a,w)=>a+w.actual.minutes,0),prs=SK.personalRecords(state);
    const prCards=prs.records.map(r=>`<div class="pr-card ${r.seconds?'has-pr':''}"><span>${esc(r.label)}</span><strong>${r.seconds?(r.estimated?'~':'')+formatSeconds(r.seconds):'--'}</strong><small>${r.date?`${esc(dateLabel(r.date,{year:'numeric'}))}${r.estimated?' · berekend uit gemiddeld tempo':''}`:'Nog geen resultaat'}</small>${r.workoutId?btn('Bekijk','detail',`data-id="${esc(r.workoutId)}"`,'ghost compact'):''}</div>`).join('');
    return heading('Kijk wat je al hebt gedaan.','Werkelijke trainingen, persoonlijke records en je ontwikkeling.')+`<section class="card"><div class="card-header"><div><h2>Persoonlijke records</h2><p>Exacte best efforts uit Strava krijgen voorrang; anders gebruikt MijnLoop alleen bijna-exacte geregistreerde afstanden.</p></div>${icon('target',22)}</div><div class="pr-grid">${prCards}</div><div class="pr-summary"><div><span>Langste loop</span><strong>${prs.longest?num(prs.longest.km)+' km':'--'}</strong></div><div><span>Snelste gemiddelde tempo vanaf 3 km</span><strong>${prs.fastest?formatSeconds(prs.fastest.paceSeconds)+'/km':'--'}</strong></div></div></section><div class="progress-grid mt"><section class="card"><div class="card-header"><div><h2>Hardlopen per week</h2><p>De afgelopen acht kalenderweken</p></div>${icon('chart',22)}</div><div class="chart-bars" role="img" aria-label="Geplande en werkelijk gelopen kilometers per week">${weeks.map(w=>`<div class="bar-group"><div class="bar planned" style="height:${w.planned/max*100}%" title="Gepland: ${num(w.planned)} km"></div><div class="bar" style="height:${w.actual/max*100}%" title="Gelopen: ${num(w.actual)} km"></div><span class="bar-label">${esc(dateLabel(w.start))}</span></div>`).join('')}</div><div class="legend"><span><i class="light"></i>Gepland</span><span><i></i>Gelopen</span></div><details class="faq mt"><summary>Getallen als tabel bekijken</summary><table class="data-table"><thead><tr><th>Week vanaf</th><th>Gepland</th><th>Gelopen</th></tr></thead><tbody>${weeks.map(w=>`<tr><td>${dateLabel(w.start)}</td><td>${num(w.planned)} km</td><td>${num(w.actual)} km</td></tr>`).join('')}</tbody></table></details></section><section class="card"><div class="card-header"><h2>Jouw totaal</h2><span class="tag muted">Alle registraties</span></div><div class="stat-number">${num(allKm)} <small>km hardgelopen</small></div><div class="key-value"><span>Afgeronde activiteiten</span><strong>${done.length}</strong></div><div class="key-value"><span>Sportminuten</span><strong>${num(minutes)}</strong></div><div class="key-value"><span>Langste gelopen afstand</span><strong>${num(Math.max(0,...runs.map(w=>w.actual.km)))} km</strong></div><div class="button-row mt">${btn('PDF voor fysio','physio-pdf','','primary compact')}${btn('Mijn gegevens exporteren','export-json','','ghost compact')}</div></section></div><section class="card mt"><div class="card-header"><h2>Trainingshistorie</h2><span class="tag muted">Laatste 40 activiteiten</span></div><div class="workout-list">${done.length?done.slice(0,40).map(w=>workoutCard(w)).join(''):'<div class="empty">Je eerste afgeronde training verschijnt hier.</div>'}</div></section>`;
  }
  function slotRow(s){const kind=s.kind==='easy'?'short':(s.kind||'short');return `<div class="slot-row" data-slot-id="${esc(s.id)}"><label>Dag<select name="day">${opts(Object.fromEntries(days.map((x,i)=>[i,x])),s.day)}</select></label><label>Sport<select name="sport">${opts(sports,s.sport)}</select></label><label>Begintijd<input name="time" type="time" value="${esc(s.time)}" required><span class="field-help">Alleen het startmoment staat vast. De planner berekent de trainingsduur zelf.</span></label><label>Hardloopdag<select name="runKind"><option value="short" ${kind==='short'?'selected':''}>Korte / rustige loop</option><option value="long" ${kind==='long'?'selected':''}>Lange afstand</option><option value="interval" ${kind==='interval'?'selected':''}>Interval</option></select><span class="field-help">Alleen gebruikt als sport = hardlopen.</span></label>${btn(icon('trash',16),'remove-slot','aria-label="Sportmoment verwijderen"','ghost icon-btn')}</div>`;}
  function stravaCard(){
    const garminImported=state?.workouts?.filter(w=>w.external?.provider==='strava'&&/garmin/i.test(w.external?.deviceName||'')).length||0;
    if(demo)return `<section class="card"><div class="card-header"><div><h2>Strava + Garmin import</h2><p>Automatische trainingsdata</p></div>${icon('cloud',21)}</div><p class="small muted">In de demo is geen echte koppeling actief. In de live app kan MijnLoop hardloopactiviteiten uit Strava ophalen. Garmin Connect kan automatisch naar Strava synchroniseren; MijnLoop importeert die loop daarna uit Strava.</p></section>`;
    if(stravaStatus.available===false)return `<section class="card"><div class="card-header"><div><h2>Strava + Garmin import</h2><p>Eenmalige installatie nodig</p></div>${icon('cloud',21)}</div><p class="small muted">De rest van MijnLoop werkt gewoon zonder koppeling. Voor automatische import gebruik je de optionele lokale-account Strava-bridge in Supabase. De login zelf blijft volledig lokaal en gebruikt geen Supabase Auth.</p><div class="notice mt">Garmin-gebruiker? Laat Garmin Connect automatisch naar Strava synchroniseren; MijnLoop haalt je hardloopactiviteit daarna uit Strava.</div></section>`;
    if(stravaStatus.connected)return `<section class="card"><div class="card-header"><div><h2>Strava gekoppeld</h2><p>${esc(stravaStatus.athleteName||'Jouw account')}</p></div><span class="tag">Verbonden</span></div><div class="key-value"><span>Laatste import</span><strong>${stravaStatus.lastSync?esc(new Date(stravaStatus.lastSync).toLocaleString('nl-NL',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})):'Nog niet'}</strong></div><p class="small muted mt">MijnLoop synchroniseert bij openen en via de gewone synchronisatieknop, maximaal ongeveer eens per 15 minuten. Afstand, tijd, tempo, hoogte, apparaat, beschikbare best efforts en waar beschikbaar hartslag/cadans worden overgenomen.</p>${garminImported?`<div class="notice mt"><strong>Garmin via Strava:</strong> ${garminImported} geimporteerde loop${garminImported===1?'':'jes'} herkend aan de apparaatnaam.</div>`:''}<div class="button-row mt">${btn('Nu Strava synchroniseren','strava-sync','','primary compact')}${btn('Koppeling verbreken','strava-disconnect','','danger compact')}</div><div class="notice mt">Geimporteerde trainingen krijgen eerst een neutrale inspanning. Bevestig RPE en reden bij de training als je wilt dat die training je lokale schema mee bijstuurt.</div></section>`;
    return `<section class="card"><div class="card-header"><div><h2>Strava + Garmin import</h2><p>Trainingsdata automatisch overnemen</p></div>${icon('cloud',21)}</div><p class="small muted">Koppel Strava eenmalig. Daarna controleert MijnLoop automatisch op nieuwe hardloopactiviteiten bij openen/inloggen en via de gewone synchronisatieknop (maximaal ongeveer eens per 15 minuten). Gebruik je Garmin, verbind Garmin Connect met Strava; nieuwe Garmin-activiteiten verschijnen automatisch in Strava en worden daarna door MijnLoop ingelezen.</p><div class="button-row mt">${btn('Strava koppelen','strava-connect','','primary')}</div><p class="small muted mt">MijnLoop vraagt alleen leesrechten voor activiteiten en bewaart je Strava client-secret nooit in GitHub of de browser.</p></section>`;
  }
  function settingsPage(){
    const p=state.profile||{name:'',goal:'fit',baseWeeklyKm:'',longestKm:'',pace:6.5,raceDate:'',autoAdapt:true,horizon:12,planMode:'fixed'};
    const slots=state.profile?state.slots:[{id:uid(),day:1,time:'18:30',sport:'run',minutes:55,kind:'short'},{id:uid(),day:3,time:'18:30',sport:'run',minutes:65,kind:'interval'},{id:uid(),day:6,time:'09:30',sport:'run',minutes:120,kind:'long'}];
    const mode=p.planMode||(p.raceDate?'goal':'fixed');
    const planOptions=`<option value="goal" ${mode==='goal'?'selected':''}>Gebruik doeldatum</option>`+Array.from({length:49},(_,i)=>i+4).map(n=>`<option value="${n}" ${mode==='fixed'&&Number(p.horizon)===n?'selected':''}>${n} weken vooruit</option>`).join('');
    return heading(state.profile?'Jouw doel. Jouw hardloopweek.':'Begin bij waar je nu staat.',state.profile?'Je vaste dagen en lokale schema bepalen samen de opbouw.':'Vul je echte startniveau in; MijnLoop rekent daarna lokaal je planning uit.')+`<div class="settings-grid"><section class="card"><form id="profile-form"><div class="form-error" role="alert"></div><fieldset><legend>Persoonlijk doel</legend><div class="form-grid"><label>Voornaam<input name="name" maxlength="40" value="${esc(p.name)}" placeholder="Jouw voornaam" required></label><label>Mijn doel<select name="goal">${opts(goals,p.goal)}</select></label><label>Doeldatum (optioneel)<input name="raceDate" type="date" value="${esc(p.raceDate)}"><span class="field-help">Kies bij Planning vooruit voor 'Gebruik doeldatum' als het schema exact naar deze datum moet lopen.</span></label><label>Rustig tempo (min/km)<input name="pace" type="text" inputmode="numeric" pattern="[0-9]{1,2}:[0-5][0-9]" value="${paceDisplay(p.pace)}" placeholder="6:30" required><span class="field-help">Voer bijvoorbeeld 6:30 in voor 6 minuten 30 seconden per kilometer.</span></label><label>Gemiddeld hardlopen per week<input name="baseWeeklyKm" type="number" min="1" max="150" step="0.1" value="${p.baseWeeklyKm}" placeholder="Bijvoorbeeld 18" required><span class="field-help">Je werkelijke gemiddelde van de laatste 4 weken, niet je gewenste aantal.</span></label><label>Recent langste rustige loop (km)<input name="longestKm" type="number" min="1" max="150" step="0.1" value="${p.longestKm}" placeholder="Bijvoorbeeld 7" required><span class="field-help">Een afstand die je recent daadwerkelijk kon lopen.</span></label><label>Planning vooruit<select name="planRange">${planOptions}</select><span class="field-help">Kies doeldatum of een vaste periode van 4 t/m 52 weken. Alle modellen staan lokaal in de app.</span></label><label>Tijdzone<input readonly value="Europe/Amsterdam"><span class="field-help">Zomer- en wintertijd worden meegenomen.</span></label></div></fieldset><div class="form-separator"></div><fieldset><legend>Je vaste sportmomenten</legend><p class="small muted mb">Geef per sportmoment alleen de dag en beschikbare begintijd op. Bij hardloopdagen kies je kort, lang of interval. De planner berekent afstand en duur daarna automatisch uit je doel, trainingsfase en tempo. Kies maximaal één lange dag en één intervaldag per week.</p><div id="slot-rows">${slots.map(slotRow).join('')}</div>${btn(icon('plus',15)+' Sportmoment toevoegen','add-slot','','ghost compact')}</fieldset><div class="form-separator"></div>${notificationSettingsCard()}<div class="form-separator"></div><label class="checkline"><input name="autoAdapt" type="checkbox" ${p.autoAdapt?'checked':''}><span>Schema automatisch lokaal aanpassen na iedere registratie.<span class="field-help" style="display:block">Comfortabele goede reeksen kunnen een kleine stap omhoog geven. Zware of ingekorte trainingen verlagen tijdelijk de belasting. Bij pijn of ziekte pauzeert de planning altijd.</span></span></label><div class="notice mt"><strong>Volledig lokaal:</strong> MijnLoop bevat voorgerekende hardloopmodellen voor iedere lengte van 4 t/m 52 weken. Opslaan, opnieuw beoordelen en aanpassen na een training gebeurt volledig lokaal.</div><button type="submit" class="btn primary">${state.profile?'Instellingen opslaan en schema opbouwen':'Mijn eerste schema maken'} ${icon('arrow',16)}</button></form></section><div class="stack"><section class="card"><div class="card-header"><h2>Drie soorten hardloopdagen</h2>${icon('run',23)}</div><div class="key-value"><span>Korte / rustige loop</span><strong>basis & herstel</strong></div><div class="key-value"><span>Lange afstand</span><strong>duurvermogen</strong></div><div class="key-value"><span>Interval</span><strong>concrete sessie in agenda</strong></div><p class="small muted mt">Intervaltrainingen wisselen per fase en doel. Tijdens herstel- en taperweken worden ze bewust lichter.</p></section>${stravaCard()}<section class="card"><div class="card-header"><h2>Account en privacy</h2>${icon('shield',21)}</div><p class="small muted">${demo?'Je zit in de fictieve demo. Er worden geen echte accountgegevens opgeslagen.':'Je login en sportgegevens staan lokaal in deze browser. Supabase Auth wordt niet gebruikt.'}</p><div class="button-row mt">${btn('Gegevens exporteren','export-json','','compact')}${demo?'':btn('Backup importeren','import-json','','compact')}${demo?'':btn('Wachtwoord wijzigen','change-password','','compact')}${btn('Uitloggen','logout','','compact')}</div><div class="divider"></div><p class="small muted">Beheer van gebruikers gebeurt op de losse <a href="./admin.html">beheerderspagina</a>. Voor gebruik op een ander apparaat kun je via beheer een volledige lokale backup exporteren/importeren.</p></section><section class="card"><h3>Handige hardloopfuncties</h3><p class="small muted mt">MijnLoop toont je trainingsfase, bewaakt de 32 km-grens voor marathontraining, geeft intervalinhoud per sessie, houdt een lokale aanpassingshistorie bij en kan een fysio-overzicht als PDF afdrukken.</p></section></div></div>`;
  }
  function physioModal(){
    showModal('PDF voor fysiotherapeut','Maak een overzicht van wat je werkelijk hebt gedaan.',`<form id="physio-form"><div class="form-error" role="alert"></div><label>Periode<select name="period"><option value="week">Afgelopen week / deze kalenderweek</option><option value="month" selected>Deze maand</option><option value="quarter">Dit kwartaal</option><option value="year">Dit jaar</option></select></label><label class="checkline mt"><input name="notes" type="checkbox"><span>Mijn eigen trainingsnotities ook opnemen.<span class="field-help" style="display:block">Standaard staan alleen sport, datum, duur, afstand, inspanning en gepland versus werkelijk in het rapport.</span></span></label><div class="notice mt">Na klikken opent het afdrukvenster. Kies daar <strong>Opslaan als PDF</strong>. Het rapport wordt lokaal in je browser opgebouwd en niet naar een extra dienst gestuurd.</div><div class="modal-actions">${btn('Annuleren','close-modal')}<button type="submit" class="btn primary">Rapport maken</button></div></form>`);
  }
  function periodStart(period,today){
    if(period==='week') return monday(today);
    if(period==='month') return today.slice(0,7)+'-01';
    if(period==='year') return today.slice(0,4)+'-01-01';
    const month=Number(today.slice(5,7)),q=Math.floor((month-1)/3)*3+1;return today.slice(0,4)+'-'+String(q).padStart(2,'0')+'-01';
  }
  function openPhysioReport(period,includeNotes){
    const today=isoDay(),start=periodStart(period,today), rows=state.workouts.filter(w=>w.actual&&['done','skipped'].includes(w.status)&&w.date>=start&&w.date<=today).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
    const done=rows.filter(w=>w.status==='done'),runs=done.filter(w=>w.sport==='run'),minutes=done.reduce((a,w)=>a+Number(w.actual.minutes||0),0),km=runs.reduce((a,w)=>a+Number(w.actual.km||0),0),avgRpe=done.length?done.reduce((a,w)=>a+Number(w.actual.rpe||0),0)/done.length:0;
    const breakdown=Object.entries(done.reduce((m,w)=>(m[w.sport]=(m[w.sport]||0)+1,m),{})).map(([k,v])=>`${sports[k]||k}: ${v}`).join(' · ')||'Geen afgeronde activiteiten';
    const notesHead=includeNotes?'<th>Notitie</th>':'';
    const table=rows.map(w=>`<tr><td>${esc(dateLabel(w.date,{year:'numeric'}))}</td><td>${esc(sports[w.sport]||w.sport)}</td><td>${num(w.actual.minutes)} min</td><td>${w.sport==='run'?num(w.actual.km)+' km':'-'}</td><td>${w.actual.rpe}/10</td><td>${w.sport==='run'?num(w.actual.plannedKm)+' → '+num(w.actual.km)+' km':'-'}</td>${includeNotes?`<td>${esc(w.actual.notes||'')}</td>`:''}</tr>`).join('')||`<tr><td colspan="${includeNotes?7:6}">Geen geregistreerde activiteiten in deze periode.</td></tr>`;
    const win=window.open('','_blank');if(!win)throw new Error('Je browser blokkeert het rapportvenster. Sta pop-ups voor MijnLoop toe en probeer opnieuw.');
    win.document.write(`<!doctype html><html lang="nl"><head><meta charset="utf-8"><title>MijnLoop rapport ${start} - ${today}</title><style>@page{size:A4;margin:14mm}body{font-family:Arial,sans-serif;color:#20251f;font-size:11px;line-height:1.4}h1{font-size:24px;margin:0 0 4px}h2{font-size:15px;margin:22px 0 8px}.muted{color:#667066}.meta{display:flex;gap:24px;flex-wrap:wrap;margin:18px 0}.stat{border:1px solid #d8ddd5;border-radius:8px;padding:10px 14px;min-width:120px}.stat b{display:block;font-size:18px}table{width:100%;border-collapse:collapse;margin-top:8px}th,td{border-bottom:1px solid #ddd;padding:7px 5px;text-align:left;vertical-align:top}th{background:#f2f5ef;font-size:10px;text-transform:uppercase}footer{margin-top:24px;border-top:1px solid #ddd;padding-top:8px;color:#667066;font-size:9px}@media print{button{display:none}}</style></head><body><h1>MijnLoop - sportoverzicht</h1><div class="muted">${esc(state.profile?.name||'Sporter')} · ${esc(dateLabel(start,{year:'numeric'}))} t/m ${esc(dateLabel(today,{year:'numeric'}))}</div><div class="meta"><div class="stat"><b>${done.length}</b>afgeronde activiteiten</div><div class="stat"><b>${num(minutes)} min</b>totale sporttijd</div><div class="stat"><b>${num(km)} km</b>hardgelopen</div><div class="stat"><b>${num(Math.max(0,...runs.map(w=>w.actual.km)))} km</b>langste loop</div><div class="stat"><b>${num(avgRpe)}/10</b>gem. inspanning</div></div><p><strong>Verdeling:</strong> ${esc(breakdown)}. Overgeslagen/gemiste geregistreerde momenten: ${rows.filter(w=>w.status==='skipped').length}.</p><h2>Activiteiten</h2><table><thead><tr><th>Datum</th><th>Sport</th><th>Duur</th><th>Afstand</th><th>RPE</th><th>Gepland → werkelijk</th>${notesHead}</tr></thead><tbody>${table}</tbody></table><footer>Gegenereerd met MijnLoop op ${esc(dateLabel(today,{year:'numeric'}))}. Dit overzicht is een registratie van ingevoerde sportactiviteiten en geen medisch verslag of diagnose.</footer><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);win.document.close();
  }
  function detailModal(id){
    const w=state.workouts.find(x=>x.id===id);if(!w)return;const actual=w.actual;
    const intervalBlock=w.kind==='interval'&&w.interval?`<div class="notice mt"><strong>${esc(w.interval.summary)}</strong><br>${esc(w.interval.detail)}<br><span class="small">${esc(w.interval.effort||'')}</span></div>`:'';
    const externalBlock=w.external?.provider==='strava'?`<div class="notice mt"><strong>Geimporteerd uit Strava</strong>${w.external.deviceName?` · ${esc(w.external.deviceName)}`:''}${w.external.elevationGain?` · ${num(w.external.elevationGain)} m stijging`:''}${w.actual?.km?` · ${esc(actualPace(w))}`:''}${w.external.averageHeartrate?` · gem. ${Math.round(w.external.averageHeartrate)} bpm`:''}${w.external.maxHeartrate?` · max ${Math.round(w.external.maxHeartrate)} bpm`:''}${w.external.averageCadence?` · cadans ${Math.round(w.external.averageCadence)}`:''}${w.external.url?`<br><a href="${esc(w.external.url)}" target="_blank" rel="noopener noreferrer">View on Strava</a>`:''}${w.actual?.needsReview?'<br><span class="small">Bevestig hieronder je inspanning en reden als je wilt dat deze training het lokale schema mee bijstuurt.</span>':''}</div>`:'';
    const guidance=w.kind==='long'?'Rustige duurloop: houd de inspanning beheerst en forceer de geplande afstand niet.':w.kind==='interval'?'De snelle stukken horen controleerbaar te blijven. Stop of maak het rustiger als de sessie niet goed voelt.':w.sport==='run'?'Korte rustige loop: comfortabel tempo, bedoeld om de totale week goed vol te houden.':'Dit sportmoment blijft los van het hardloopschema; prestaties worden niet omgerekend naar hardloopkilometers.';
    showModal(w.title,`${dateLabel(w.date,{weekday:'long',year:'numeric'})} om ${w.time}`,`<div class="metric-banner"><div><strong>${num(w.km)} ${w.sport==='run'?'km':''}</strong><span>${w.sport==='run'?'gepland':'Afstand niet gebruikt'}</span></div><div><strong>${num(w.minutes)} min</strong><span>geplande tijdsduur</span></div></div>${w.sport==='run'?`<div class="tags"><span class="tag muted">${esc(runKindLabel(w.kind))}</span>${w.planPhase?`<span class="tag">${esc(w.planPhase)}</span>`:''}</div>`:''}${tags(w)}${intervalBlock}${externalBlock}${actual?`<div class="notice mt"><strong>Geregistreerd:</strong> ${num(actual.km)} km / ${num(actual.minutes)} minuten${w.sport==='run'&&actual.km>0?' · '+esc(actualPace(w)):''}. Inspanning ${actual.rpe}/10.${actual.notes?'<br>'+esc(actual.notes):''}</div>`:''}${w.adaptation?`<div class="notice mt">${esc(w.adaptation)}</div>`:''}<p class="small muted mt">${esc(guidance)}</p><div class="modal-actions">${['planned','held'].includes(w.status)?btn('Aanpassen','edit',`data-id="${id}"`,''):''}${w.date<=isoDay()&&w.status!=='cancelled'?btn(actual?'Registratie wijzigen':'Training registreren','log',`data-id="${id}"`,'primary'):''}</div>`);
  }
  function logModal(id){
    const w=state.workouts.find(x=>x.id===id);if(!w)return;const a=w.actual;
    if(w.date>isoDay()){detailModal(id);return;}
    showModal('Wat heb je echt gedaan?',`${w.title} - ${dateLabel(w.date,{weekday:'long'})}`,`<div class="metric-banner"><div><strong>${num(a?.plannedKm??w.km)} km</strong><span>oorspronkelijk gepland</span></div><div><strong>${num(a?.plannedMinutes??w.minutes)} min</strong><span>geplande tijdsduur</span></div></div><form id="workout-log" data-id="${id}"><div class="form-error" role="alert"></div><div class="form-grid"><label>Werkelijke afstand (km)<input name="km" type="number" min="0" max="300" step="0.1" value="${a?.km??w.km}" required><span class="field-help">Bij kracht of padel kun je 0 invullen.</span></label><label>Werkelijke duur (minuten)<input name="minutes" type="number" min="0" max="1440" step="1" value="${a?.minutes??w.minutes}" required></label><label>Hoe zwaar voelde het?<select name="rpe">${opts({'1':'1 - zeer licht','2':'2 - heel licht','3':'3 - licht','4':'4 - ontspannen','5':'5 - gemiddeld','6':'6 - stevig','7':'7 - zwaar','8':'8 - erg zwaar','9':'9 - bijna maximaal','10':'10 - maximaal'},a?.rpe??5)}</select></label><label>Reden / hoe ging het?<select name="reason">${opts({normal:'Volgens plan / voelde goed',time:'Minder tijd beschikbaar',fatigue:'Vermoeid / te zwaar',weather:'Weer of omstandigheden',pain:'Pijn of blessure',illness:'Ziek / niet fit',missed:'Training gemist',other:'Andere reden'},a?.reason??'normal')}</select></label><label class="span2">Notitie (optioneel)<textarea name="notes" maxlength="1000" placeholder="Bijvoorbeeld: moest eerder terug voor een afspraak.">${esc(a?.notes||'')}</textarea></label></div><p class="small muted mt">Niet gesport? Vul 0 km en 0 minuten in. De planner maakt geen inhaalschuld. Bij pijn of ziekte worden toekomstige trainingen gepauzeerd.</p><div class="modal-actions">${btn('Annuleren','close-modal')}<button type="submit" class="btn primary">Opslaan en ${state.profile.autoAdapt?'schema beoordelen':'registreren'}</button></div></form>`);
  }
  function workoutForm(w,isNew){
    showModal(isNew?'Activiteit toevoegen':'Training aanpassen','Dit verandert alleen deze activiteit, niet je wekelijkse vaste momenten.',`<form id="${isNew?'workout-add':'workout-edit'}" ${isNew?'':`data-id="${w.id}"`}><div class="form-error" role="alert"></div><div class="form-grid"><label class="span2">Naam<input name="title" maxlength="80" value="${esc(w.title||'')}" required></label><label>Sport<select name="sport">${opts(sports,w.sport||'run')}</select></label><label>Datum<input name="date" type="date" value="${esc(w.date)}" required></label><label>Begintijd<input name="time" type="time" value="${esc(w.time||'18:30')}" required></label><label>Duur (minuten)<input name="minutes" type="number" min="15" max="300" value="${w.minutes||45}" required></label><label>Afstand (km)<input name="km" type="number" min="0" max="100" step="0.1" value="${w.km||0}" required></label><label>Soort loop<select name="kind">${opts({short:'Korte / rustige loop',long:'Lange duurloop',interval:'Interval'},w.kind==='easy'?'short':(w.kind||'short'))}</select></label><label class="checkline span2"><input name="locked" type="checkbox" ${w.locked?'checked':''}><span>Deze hele training vastzetten, ook de afstand.<span class="field-help" style="display:block">Normaal blijven alleen datum en tijd vast. Een veiligheidspauze geldt ook voor vastgezette trainingen.</span></span></label></div><div class="modal-actions">${isNew?'':btn('Verwijderen','cancel-workout',`data-id="${w.id}"`,'danger')}${btn('Annuleren','close-modal')}<button type="submit" class="btn primary">${isNew?'Activiteit toevoegen':'Wijziging opslaan'}</button></div></form>`);
  }
  function shareModal(){
    showModal('Je sportagenda, ook in je eigen agenda.','Met lokale accounts is een los .ics-bestand beschikbaar.',`<div class="notice"><strong>Lokale accountmodus:</strong> je sportgegevens staan niet op een server. Daarom kan een live agenda-abonnement niet zelfstandig verversen wanneer MijnLoop gesloten is.</div><p class="small muted mt">Je kunt wel op ieder moment een nieuw .ics-bestand downloaden en dat in Apple Agenda, Google Agenda of Outlook importeren.</p><div class="button-row mt">${btn('Agenda als .ics downloaden','export-ics','','primary')}</div>`);
  }
  function linkHTML(url){return `<div class="link-box"><label>Persoonlijke agenda-URL<input id="feed-url" readonly value="${esc(url)}"></label><div class="button-row">${btn('Kopieer link','copy-share','','primary compact')}<a class="btn compact" href="${esc(url.replace(/^https:/,'webcal:'))}">Open als agenda-abonnement</a></div></div>`;}
  function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function loadStravaStatus(silent=true){
    if(demo||!state||!SK.DB.configured()){stravaStatus={available:false,connected:false,athleteName:'',lastSync:null};return stravaStatus;}
    try{const data=await SK.DB.invoke('strava',{action:'status'});stravaStatus={available:true,connected:!!data.connected,athleteName:data.athleteName||'',lastSync:data.lastSync||null};return stravaStatus;}
    catch(e){stravaStatus={available:false,connected:false,athleteName:'',lastSync:null};if(!silent)toast('De optionele lokale-account Strava-bridge is nog niet geinstalleerd in Supabase.');return stravaStatus;}
  }
  function knownExternalIds(){return state.workouts.map(w=>w.external?.provider==='strava'?w.external.providerId:null).filter(Boolean).slice(-150);}
  async function syncStrava(silent=false){
    if(demo||!state||busy)return {imported:0,updated:0};
    const status=await loadStravaStatus(true);if(!status.available||!status.connected){if(!silent&&status.available)toast('Koppel Strava eerst bij Instellingen.');return {imported:0,updated:0};}
    try{
      const data=await SK.DB.invoke('strava',{action:'sync',knownIds:knownExternalIds()});
      const c=clone(state),result=SK.mergeExternalRuns(c,Array.isArray(data.activities)?data.activities:[]);
      c.integrations={...(c.integrations||{}),strava:{connected:true,lastSync:data.lastSync||new Date().toISOString(),athleteName:data.athleteName||status.athleteName}};
      if(result.imported||result.updated)state=await SK.DB.save(c);else state=c;
      stravaStatus={available:true,connected:true,athleteName:data.athleteName||status.athleteName,lastSync:data.lastSync||new Date().toISOString()};render();
      if(!silent)toast(result.imported||result.updated?`${result.imported} nieuwe en ${result.updated} bijgewerkte Strava-loop${result.imported+result.updated===1?'':'jes'} verwerkt.`:'Strava is bijgewerkt; geen nieuwe hardloopactiviteiten.');
      return result;
    }catch(e){if(!silent)toast(e.message);return {imported:0,updated:0};}
  }
  async function autoStravaSync(){
    if(demo||!state||busy||!navigator.onLine)return;
    const status=await loadStravaStatus(true);if(!status.connected)return;
    const last=status.lastSync?Date.parse(status.lastSync):0;if(Date.now()-last<15*60*1000)return;
    await syncStrava(true);
  }
  async function sync(silent=false){if(demo){if(!silent)toast('Dit is een lokale demo.');return;}if(!state||busy)return;try{const data=await SK.DB.load();state=data.state;syncLabel='Lokaal opgeslagen';await loadStravaStatus(true);render();if(stravaStatus.connected)await syncStrava(true);if(!silent)toast('Lokale gegevens opnieuw geladen'+(stravaStatus.connected?' en Strava gecontroleerd.':'.'));}catch(e){if(/sessie/.test(e.message)){await SK.DB.logout();state=null;renderAuth();}if(!silent)toast(e.message);}}
  async function handleAction(el){
    const action=el.dataset.action,id=el.dataset.id;
    if(busy&&action!=='copy-share')return;
    if(action==='close-modal'){closeModal();return;}
    if(action==='start-demo'){demo=true;state=SK.demoState();view='overview';anchor=selectedDay=isoDay();render();return;}
    if(action==='reset-demo'){if(confirm('Fictieve demo terugzetten? Je wijzigingen in deze demo verdwijnen.')){state=SK.demoState();render();}return;}
    if(action==='logout'){if(!demo)await SK.DB.logout();demo=false;state=null;shareUrl='';closeModal();renderAuth();return;}
    if(!state)return;
    if(action==='nav'){view=el.dataset.view;render();scrollTo(0,0);return;}
    if(action==='sync'){await sync();return;}
    if(action==='day'){selectedDay=el.dataset.date;render();return;}
    if(action==='detail'){detailModal(id);return;}
    if(action==='log'){logModal(id);return;}
    if(action==='edit'){const w=state.workouts.find(x=>x.id===id);if(w)workoutForm(w,false);return;}
    if(action==='add-workout'){workoutForm({date:el.dataset.date||isoDay(),title:'Extra sportmoment',sport:'run',time:'18:30',minutes:45,km:5},true);return;}
    if(action==='add-slot'){document.getElementById('slot-rows')?.insertAdjacentHTML('beforeend',slotRow({id:uid(),day:0,time:'18:30',sport:'strength',kind:'short'}));return;}
    if(action==='remove-slot'){el.closest('.slot-row').remove();return;}
    if(action==='share'){if(!state.profile){toast('Maak eerst je persoonlijke schema.');return;}shareModal();return;}
    if(action==='strava-connect'){if(demo)return;try{const data=await SK.DB.invoke('strava',{action:'start',returnUrl:location.origin+location.pathname});if(!data?.url)throw new Error('Strava-koppeling kon niet worden gestart.');location.href=data.url;}catch(e){toast(e.message);}return;}
    if(action==='strava-sync'){await syncStrava(false);return;}
    if(action==='strava-disconnect'){if(!confirm('Strava loskoppelen? Reeds geimporteerde trainingen blijven in MijnLoop staan.'))return;try{await SK.DB.invoke('strava',{action:'disconnect'});stravaStatus={available:true,connected:false,athleteName:'',lastSync:null};render();toast('Strava is losgekoppeld.');}catch(e){toast(e.message);}return;}
    if(action==='export-ics'){download(SK.calendarText(state,{owner:demo?'demo':SK.DB.user?.id,minimal:document.getElementById('share-minimal')?.checked??true}),'text/calendar;charset=utf-8','mijnloop-agenda.ics');toast('Momentopname gedownload; dit bestand synchroniseert niet.');return;}
    if(action==='import-json'){const input=document.createElement('input');input.type='file';input.accept='application/json,.json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text()),candidate=data?.state||data;SK.validateState(candidate);if(!confirm('Deze backup vervangt de lokale sportgegevens van dit account. Doorgaan?'))return;await commit(candidate,'Backup geimporteerd.');}catch(e){toast('Importeren mislukt: '+e.message);}};input.click();return;}
    if(action==='change-password'){showModal('Wachtwoord wijzigen','Dit wijzigt alleen het lokale wachtwoord van dit account op dit apparaat.',`<form id="change-password-form"><div class="form-error" role="alert"></div><label>Huidig wachtwoord<input name="oldPassword" type="password" autocomplete="current-password" required></label><label>Nieuw wachtwoord<input name="newPassword" type="password" autocomplete="new-password" required></label><label>Herhaal nieuw wachtwoord<input name="confirm" type="password" autocomplete="new-password" required></label><div class="modal-actions">${btn('Annuleren','close-modal')}<button class="btn primary" type="submit">Wijzigen</button></div></form>`);return;}
    if(action==='export-json'){download(JSON.stringify({exportedAt:new Date().toISOString(),state},null,2),'application/json','mijnloop-backup-'+isoDay()+'.json');toast('Persoonlijke gegevens gedownload. Bewaar dit bestand veilig.');return;}
    if(action==='notifications'){notificationCenter();return;}
    if(action==='nav-notifications'){closeModal();view='settings';render();setTimeout(()=>document.querySelector('[name="notificationsEnabled"]')?.scrollIntoView({behavior:'smooth',block:'center'}),50);return;}
    if(action==='enable-notifications'){
      if(!('Notification' in window)){toast('Systeemmeldingen worden in deze browser niet ondersteund. Op iPhone: installeer MijnLoop eerst via Zet op beginscherm.');return;}
      const permission=await Notification.requestPermission();render();if(permission==='granted'){await updateAppBadge();toast('Meldingen zijn toegestaan op dit apparaat.');await showDeviceNotification({key:'test-permission',title:'MijnLoop meldingen staan aan',body:'Je ontvangt meldingen volgens de categorieen die je bij Instellingen hebt aangezet.'});}else toast('Meldingen zijn niet toegestaan. Je kunt dit later in de apparaatinstellingen wijzigen.');return;
    }
    if(action==='test-notification'){if(notificationPermission()!=='granted'){toast('Sta eerst meldingen toe op dit apparaat.');return;}await showDeviceNotification({key:'test-'+Date.now(),title:'Testmelding van MijnLoop',body:'Meldingen werken op dit apparaat.'});toast('Testmelding verstuurd.');return;}
    if(action==='physio-pdf'){physioModal();return;}
    if(action==='cal-mode'){calendarMode=el.dataset.mode;render();return;}
    if(action==='cal-today'){anchor=isoDay();render();return;}
    if(action==='cal-prev'||action==='cal-next'){const delta=action==='cal-prev'?-1:1;if(calendarMode==='week')anchor=addDays(anchor,delta*7);else{const d=new Date(anchor.slice(0,7)+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+delta);anchor=d.toISOString().slice(0,10);}render();return;}
    if(action==='recalculate'){const c=clone(state),window=SK.planWindow(c.profile,isoDay());SK.generatePlan(c,{weeks:window.weeks});await commit(c,'Schema lokaal opnieuw beoordeeld en opnieuw opgebouwd.');return;}
    if(action==='reset-coach'){if(!state.adjustments?.length){toast('Er is geen Coach-historie om te resetten.');return;}if(!confirm('Weet je zeker dat je de Coach-historie wilt resetten?\n\nAlle beoordelingen en het overzicht van eerdere aanpassingen worden gewist. Je trainingen, resultaten, instellingen en huidige planning blijven behouden.'))return;const c=clone(state);SK.resetCoachHistory(c);await commit(c,'Coach-historie is gereset.');return;}
    if(action==='resume'){showModal('Bewust opnieuw beginnen','Bevestig zelf een passend huidig startniveau. De app kan herstel niet medisch beoordelen.',`<form id="resume-form"><div class="form-error" role="alert"></div><div class="notice warning">Hervat niet om gemiste kilometers in te halen. Bespreek aanhoudende klachten met een deskundige.</div><div class="form-grid"><label>Passend weektotaal (km)<input name="weekly" type="number" min="1" max="150" step="0.1" placeholder="Jouw huidige basis" required></label><label>Passende langste loop (km)<input name="longest" type="number" min="1" max="150" step="0.1" placeholder="Jouw huidige niveau" required></label></div><label class="checkline mt"><input type="checkbox" required><span>Ik beoordeel zelf of hervatten passend is en bevestig dit startniveau.</span></label><div class="modal-actions">${btn('Op pauze blijven','close-modal')}<button type="submit" class="btn primary">Hervatten en opnieuw plannen</button></div></form>`);return;}
    if(action==='cancel-workout'){if(!confirm('Deze geplande activiteit verwijderen?'))return;const c=clone(state);SK.cancelWorkout(c,id);await commit(c,'Activiteit verwijderd.');closeModal();return;}
  }
  document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el){event.preventDefault();handleAction(el).catch(e=>toast(e.message));}else if(event.target.classList.contains('modal-overlay')&&!modalLocked)closeModal();});
  document.addEventListener('keydown',event=>{if(!modalRoot.firstChild)return;if(event.key==='Escape'&&!modalLocked)closeModal();if(event.key==='Tab'){const nodes=[...modalRoot.querySelectorAll('button:not(:disabled),a,input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')].filter(x=>x.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
  document.addEventListener('submit',async event=>{
    event.preventDefault();if(busy)return;const form=event.target,fd=new FormData(form);busy=true;const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
    let shouldClose=false;
    try{
      if(form.id==='login-form'){const result=await SK.DB.login(String(fd.get('username')).trim(),String(fd.get('password')));demo=false;state=result.state;view=state.profile?'overview':'settings';await loadStravaStatus(true);render();setTimeout(()=>autoStravaSync(),50);}
      else if(form.id==='profile-form'){
        const slots=[...form.querySelectorAll('.slot-row')].map(row=>{const sport=row.querySelector('[name=sport]').value,id=row.dataset.slotId,previous=state.slots.find(x=>x.id===id);return {id,day:Number(row.querySelector('[name=day]').value),sport,time:row.querySelector('[name=time]').value,minutes:Number(previous?.minutes)||60,kind:sport==='run'?row.querySelector('[name=runKind]').value:'short'};});
        const planRange=String(fd.get('planRange')||'goal'),planMode=planRange==='goal'?'goal':'fixed';
        const p={name:String(fd.get('name')).trim(),goal:fd.get('goal'),raceDate:fd.get('raceDate')||'',baseWeeklyKm:Number(fd.get('baseWeeklyKm')),longestKm:Number(fd.get('longestKm')),pace:parsePace(fd.get('pace')),autoAdapt:fd.get('autoAdapt')==='on',timezone:'Europe/Amsterdam',planMode,horizon:planMode==='fixed'?Number(planRange):Math.min(52,Math.max(4,SK.goalWeeks({raceDate:fd.get('raceDate')||''},isoDay())||12))};
        SK.validateProfile(p,slots);if(p.raceDate&&p.raceDate<isoDay())throw new Error('Kies een toekomstige doeldatum of laat deze leeg.');
        const first=!state.profile,c=clone(state);c.profile=p;c.slots=slots;c.notifications={enabled:fd.get('notificationsEnabled')==='on',appBadge:fd.get('appBadge')==='on',systemNotifications:fd.get('systemNotifications')==='on',upcoming:fd.get('notifyUpcoming')==='on',upcomingHours:Number(fd.get('upcomingHours')||4),pending:fd.get('notifyPending')==='on',pendingDelayMinutes:Number(fd.get('pendingDelayMinutes')||30)};const window=SK.planWindow(p,isoDay());SK.generatePlan(c,{weeks:window.weeks});await commit(c,'Je lokale hardloopschema is opgeslagen.');if(first){view='overview';render();scrollTo(0,0);}
      }
      else if(form.id==='workout-log'){
        const loggedId=form.dataset.id,c=clone(state);SK.logWorkout(c,loggedId,{km:Number(fd.get('km')),minutes:Number(fd.get('minutes')),rpe:Number(fd.get('rpe')),reason:fd.get('reason'),notes:fd.get('notes')});
        await commit(c,c.hold?'Training opgeslagen. De planning staat op pauze.':'Training opgeslagen en lokaal beoordeeld.');
        shouldClose=true;
      }
      else if(form.id==='workout-add'||form.id==='workout-edit'){
        const c=clone(state),patch={title:String(fd.get('title')).trim(),date:fd.get('date'),time:fd.get('time'),sport:fd.get('sport'),kind:fd.get('kind'),minutes:Number(fd.get('minutes')),km:Number(fd.get('km')),locked:fd.get('locked')==='on'};
        if(!patch.title)throw new Error('Vul een naam in.');
        if(form.id==='workout-add'){const w=SK.makeWorkout(patch);SK.checkMove(c,w);if(c.hold)w.status='held';c.workouts.push(w);SK.changeLog(c,'Activiteit toegevoegd','Handmatig sportmoment toegevoegd; niet meegerekend als nieuwe hardloopbasis.',[],new Date());}
        else SK.editWorkout(c,form.dataset.id,patch);
        await commit(c,'Activiteit opgeslagen.');shouldClose=true;
      }
      else if(form.id==='change-password-form'){if(fd.get('newPassword')!==fd.get('confirm'))throw new Error('De nieuwe wachtwoorden zijn niet hetzelfde.');await SK.DB.password(String(fd.get('oldPassword')),String(fd.get('newPassword')));toast('Lokaal wachtwoord gewijzigd.');shouldClose=true;}
      else if(form.id==='resume-form'){const c=clone(state);SK.resumePlan(c,fd.get('weekly'),fd.get('longest'));await commit(c,'Je planning is opnieuw opgebouwd.');shouldClose=true;}
      else if(form.id==='physio-form'){openPhysioReport(fd.get('period'),fd.get('notes')==='on');shouldClose=true;}
    }catch(e){showError(form,e.message);}
    finally{busy=false;if(submit?.isConnected)submit.disabled=false;if(shouldClose)closeModal();}
  });
  async function boot(){
    renderAuth();
    try{
      if(globalThis.MijnLoopLocalAuth?.currentUser?.()){
        const result=await SK.DB.load();state=result.state;view=state.profile?'overview':'settings';await loadStravaStatus(true);render();const qp=new URL(location.href).searchParams.get('strava');if(qp){history.replaceState(null,'',location.pathname);toast(qp==='connected'?'Strava is gekoppeld. Ik haal je recente hardloopactiviteiten op.':qp==='denied'?'Strava-koppeling is geannuleerd.':'Strava-koppeling kon niet worden afgerond.');}setTimeout(()=>autoStravaSync(),50);
      }
    }catch(e){toast(e.message);}
    if('serviceWorker'in navigator&&['https:','http:'].includes(location.protocol)&&!globalThis.SPORT_PREVIEW)navigator.serviceWorker.register('./sw.js').catch(()=>{});
    setInterval(()=>{if(state){updateAppBadge();maybeNotify();}},60000);
  }
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state){updateAppBadge();maybeNotify();if(!demo&&!busy&&!modalRoot.firstChild&&Date.now()-lastFocusSync>30000){lastFocusSync=Date.now();sync(true);}}});
  window.addEventListener('offline',()=>{if(state){syncLabel='Lokaal opgeslagen';render();toast('Offline. Je lokale gegevens blijven werken; Strava synchroniseert weer zodra je online bent.');}});
  window.addEventListener('online',()=>{if(state&&!demo&&!modalRoot.firstChild)sync(true);});
  boot();
})(globalThis.SK ||= {});
